import socket, subprocess, os, re, concurrent.futures, time, ipaddress, json

candidates=set()
# local hostnames/IPs
for name in [socket.gethostname(), socket.getfqdn()]:
    try:
        for info in socket.getaddrinfo(name, None, family=socket.AF_INET):
            ip=info[4][0]
            if ipaddress.ip_address(ip).is_private or ip.startswith('127.'):
                candidates.add(ip)
    except Exception: pass
# /etc/hosts
try:
    for line in open('/etc/hosts'):
        line=line.split('#',1)[0].strip()
        if not line: continue
        parts=line.split()
        if parts and re.match(r'^\d+\.\d+\.\d+\.\d+$', parts[0]):
            ip=parts[0]
            if ipaddress.ip_address(ip).is_private or ip.startswith('127.'):
                candidates.add(ip)
except Exception: pass
# resolv.conf nameservers
try:
    for line in open('/etc/resolv.conf'):
        m=re.match(r'\s*nameserver\s+(\d+\.\d+\.\d+\.\d+)', line)
        if m:
            ip=m.group(1)
            if ipaddress.ip_address(ip).is_private:
                candidates.add(ip)
except Exception: pass
# arp
try:
    for line in open('/proc/net/arp').read().splitlines()[1:]:
        parts=line.split()
        if parts:
            ip=parts[0]
            if ipaddress.ip_address(ip).is_private:
                candidates.add(ip)
except Exception: pass
# route: determine visible subnet(s)
subnets=[]
try:
    for line in open('/proc/net/route').read().splitlines()[1:]:
        parts=line.split()
        iface,dst_hex,gw_hex,flags,_,_,metric,mask_hex=parts[:8]
        dst=int(dst_hex,16); mask=int(mask_hex,16)
        # values are little endian
        dst_ip=socket.inet_ntoa(dst.to_bytes(4,'little'))
        mask_ip=socket.inet_ntoa(mask.to_bytes(4,'little'))
        if dst_ip!='0.0.0.0':
            net=ipaddress.ip_network(f'{dst_ip}/{mask_ip}', strict=False)
            if net.version==4 and net.is_private:
                subnets.append(net)
        if gw_hex!='00000000':
            gw=socket.inet_ntoa(int(gw_hex,16).to_bytes(4,'little'))
            if ipaddress.ip_address(gw).is_private:
                candidates.add(gw)
except Exception: pass

# Light TCP reachability sweep on small visible portions only (/24 cap) to discover neighbors.
ports=[22,53,80,443,445,548,631,8000,8080,8443]
def check(ip):
    hits=[]
    for p in ports:
        s=socket.socket(); s.settimeout(0.15)
        try:
            if s.connect_ex((str(ip),p))==0:
                hits.append(p)
        except Exception: pass
        finally:
            s.close()
    return str(ip), hits

scan_ips=[]
for net in subnets:
    # cap broad Docker /16 to first /24 containing local IP if possible
    if net.prefixlen < 24:
        locals_in=[ipaddress.ip_address(x) for x in list(candidates) if ipaddress.ip_address(x) in net]
        if locals_in:
            for lip in locals_in:
                n=ipaddress.ip_network(f'{lip}/24', strict=False)
                scan_ips += list(n.hosts())
        else:
            scan_ips += list(list(net.subnets(new_prefix=24))[0].hosts())
    else:
        scan_ips += list(net.hosts())
scan_ips=sorted(set(scan_ips))[:512]
open_ports={}
if scan_ips:
    with concurrent.futures.ThreadPoolExecutor(max_workers=64) as ex:
        for ip,hits in ex.map(check, scan_ips):
            if hits:
                candidates.add(ip); open_ports[ip]=hits
# re-read arp after sweep
try:
    for line in open('/proc/net/arp').read().splitlines()[1:]:
        parts=line.split()
        if parts:
            ip=parts[0]
            if ipaddress.ip_address(ip).is_private:
