    try:
        hn, aliases, _ = socket.gethostbyaddr(ip)
        names += [hn]+aliases
    except Exception: pass
    # /etc/hosts names
    try:
        for line in open('/etc/hosts'):
            line=line.split('#',1)[0].strip()
            if not line: continue
            parts=line.split()
            if parts and parts[0]==ip:
                names += parts[1:]
    except Exception: pass
    # getent hosts
    try:
        out=subprocess.check_output(['getent','hosts',ip], text=True, timeout=1).strip()
        if out:
            parts=out.split()
            if parts and parts[0]==ip: names += parts[1:]
    except Exception: pass
    # mac
    mac=''
    try:
        for line in open('/proc/net/arp').read().splitlines()[1:]:
            parts=line.split()
            if parts and parts[0]==ip:
                mac=parts[3]
    except Exception: pass
    names=sorted(set(n for n in names if n))
    source=[]
    if ip in open_ports: source.append('tcp-open:'+','.join(map(str,open_ports[ip])))
    if mac: source.append('arp:'+mac)
    if ip in [socket.gethostbyname(socket.gethostname()) if True else '']: source.append('self')
