import socket, subprocess, re, ipaddress, concurrent.futures, sys

def is_private(ip):
    try: return ipaddress.ip_address(ip).is_private or ip.startswith('127.')
    except: return False

def add(cands, ip):
    if re.match(r'^\d+\.\d+\.\d+\.\d+$', ip) and is_private(ip): cands.add(ip)

candidates=set()
for name in {socket.gethostname(), socket.getfqdn(), 'localhost'}:
    try:
        for info in socket.getaddrinfo(name, None, family=socket.AF_INET): add(candidates, info[4][0])
    except: pass
try:
    for line in open('/etc/hosts'):
        line=line.split('#',1)[0].strip()
        if line:
            parts=line.split(); add(candidates, parts[0])
except: pass
try:
    for line in open('/etc/resolv.conf'):
        m=re.match(r'\s*nameserver\s+(\d+\.\d+\.\d+\.\d+)', line)
        if m: add(candidates, m.group(1))
except: pass
try:
    for line in open('/proc/net/arp').read().splitlines()[1:]:
        parts=line.split(); add(candidates, parts[0])
except: pass
try:
    for line in open('/proc/net/route').read().splitlines()[1:]:
        parts=line.split();
        if len(parts)>=3 and parts[2] != '00000000':
            add(candidates, socket.inet_ntoa(int(parts[2],16).to_bytes(4,'little')))
except: pass

# Probe only 172.17.0.1-20 because this namespace exposes Docker bridge only.
ports=[22,53,80,443,2375,2376,8000,8080]
def probe(ip):
    hits=[]
    for p in ports:
        s=socket.socket(); s.settimeout(0.08)
        try:
            if s.connect_ex((ip,p))==0: hits.append(p)
        except: pass
        finally: s.close()
    return ip,hits
ips=[f'172.17.0.{i}' for i in range(1,21)]
with concurrent.futures.ThreadPoolExecutor(max_workers=20) as ex:
    for ip,hits in ex.map(probe, ips):
        if hits: candidates.add(ip)
# refresh ARP
try:
    arp_lines=open('/proc/net/arp').read().splitlines()[1:]
except: arp_lines=[]
arp={}
for line in arp_lines:
    parts=line.split()
    if len(parts)>=4: arp[parts[0]]=parts[3]

def names_for(ip):
    names=[]
    try:
        hn, aliases, _=socket.gethostbyaddr(ip); names += [hn]+aliases
    except: pass
    try:
        for line in open('/etc/hosts'):
            line=line.split('#',1)[0].strip()
            if line:
                parts=line.split()
                if parts[0]==ip: names += parts[1:]
    except: pass
    try:
        out=subprocess.check_output(['getent','hosts',ip], text=True, timeout=1).strip()
        if out:
            parts=out.split()
            if parts[0]==ip: names += parts[1:]
    except: pass
    return sorted(set(names))

print('Scope: sandbox/container network namespace only (gateway host exec is disabled).')
print('Visible local IPv4: ' + ', '.join(sorted(candidates, key=lambda x: tuple(map(int,x.split('.'))))))
print('\nIP\tHostname(s)\tMAC/Note')
for ip in sorted(candidates, key=lambda x: tuple(map(int,x.split('.')))):
    note=arp.get(ip,'-')
    if ip=='172.17.0.8': note='self/container'
    print(f"{ip}\t{', '.join(names_for(ip)) or '(none found)'}\t{note}")
